17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
107	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        if (dailyRegistrationLimitReached()) {
111	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
112	        }
113	        if (cityAtCapacity(owner.getCity())) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (owner.getRegistrationDate() == null) {
117	            owner.setRegistrationDate(LocalDate.now());
118	        }
119	        owner.setCity(resolveCity(owner.getCity()));
120	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
121	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    /**
130	     * The maximum number of owners that may be registered on any single day (by registration date).
131	     */
132	    private static final long MAX_OWNERS_PER_DAY = 20;
133	
134	    /**
135	     * Determines whether the maximum number of owners for the current day has already been reached.
136	     * Owners are counted by their registration date, so once {@value #MAX_OWNERS_PER_DAY} owners
137	     * carry today's registration date no further owners may be created today.
138	     *
139	     * @return {@code true} if today's registration limit has been reached
140	     */
141	    private boolean dailyRegistrationLimitReached() {
142	        LocalDate today = LocalDate.now();
143	        long registeredToday = this.clinicService.findAllOwners().stream()
144	            .filter(existing -> today.equals(existing.getRegistrationDate()))
145	            .count();
146	        return registeredToday >= MAX_OWNERS_PER_DAY;
147	    }
148	
149	    /**
150	     * The maximum number of owners that may be registered in any single city.
151	     */
152	    private static final long MAX_OWNERS_PER_CITY = 8;
153	
154	    /**
155	     * Determines whether the given city has already reached its capacity of
156	     * {@value #MAX_OWNERS_PER_CITY} owners. Owners are counted per city ignoring letter case, so
157	     * once a city holds {@value #MAX_OWNERS_PER_CITY} owners no further owners may be created there.
158	     *
159	     * @param city the raw city supplied for the owner being created, may be {@code null}
160	     * @return {@code true} if the city already contains the maximum number of owners
161	     */
162	    private boolean cityAtCapacity(String city) {
163	        if (city == null) {
164	            return false;
165	        }
166	        long ownersInCity = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
168	            .count();
169	        return ownersInCity >= MAX_OWNERS_PER_CITY;
170	    }
171	
172	    /**
173	     * Resolves the city to store for a newly created owner. If another owner is already stored in
174	     * the same city (compared ignoring letter case), that existing owner's exact spelling of the
175	     * city name is reused so that a single city is always represented consistently. Otherwise the
176	     * supplied city is title-cased (see {@link #titleCase(String)}) before being stored.
177	     *
178	     * @param city the raw city supplied for the owner being created, may be {@code null}
179	     * @return the city to store, or {@code null} if {@code city} is {@code null}
180	     */
181	    private String resolveCity(String city) {
182	        if (city == null) {
183	            return null;
184	        }
185	        return this.clinicService.findAllOwners().stream()
186	            .map(Owner::getCity)
187	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
188	            .findFirst()
189	            .orElseGet(() -> titleCase(city));
190	    }
191	
192	    /**
193	     * Title-cases a value so that the first letter of every whitespace-separated word is
194	     * upper-cased and every other letter is lower-cased, preserving the original whitespace. For
195	     * example {@code "new  york"} becomes {@code "New  York"} and {@code "LONDON"} becomes
196	     * {@code "London"}.
197	     *
198	     * @param value the raw value, may be {@code null}
199	     * @return the title-cased value, or {@code null} if {@code value} is {@code null}
200	     */
201	    private static String titleCase(String value) {
202	        if (value == null) {
203	            return null;
204	        }
205	        StringBuilder result = new StringBuilder(value.length());
206	        boolean startOfWord = true;
207	        for (int i = 0; i < value.length(); i++) {
208	            char c = value.charAt(i);
209	            if (Character.isWhitespace(c)) {
210	                startOfWord = true;
211	                result.append(c);
212	            } else {
213	                result.append(startOfWord ? Character.toUpperCase(c) : Character.toLowerCase(c));
214	                startOfWord = false;
215	            }
216	        }
217	        return result.toString();
218	    }
219	
220	    /**
221	     * Builds the customer code for a newly created owner in the given city, formatted as
222	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
223	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
